mapper.select:
select scm.code ,scm.name ,scd.cd ,scd.val from sys_code_mst scm ,sys_code_det scd where 1=1 and scm.code = scd.code and scm.use_yn = 'Y' and scd.use_yn = 'Y'
and scm.code = #{code}
and scd.cd = #{cd}
order by scm.code,scd.cd

select cqi.category_cd ,cqi.step_day_cd ,cqi.progress_type_cd ,cqi.answer_type_cd ,cqi.contents_info ,cqi.question_answer_cnt ,cqi.question ,(select name from account a where a.seq = #{accountSeq}) as account_name from coaching_question_info cqi where 1=1
and cqi.category_cd = #{categoryCd}
and cqi.step_day_cd = #{stepDayCd}
and cqi.progress_type_cd = #{progressTypeCd}
and cqi.answer_type_cd = #{answerTypeCd}
order by cqi.category_cd,cqi.step_day_cd,cqi.progress_type_cd

select cqdi.category_cd ,cqdi.step_day_cd ,cqdi.progress_type_cd ,cqdi.detail_seq ,cqdi.detail_info ,cqdi.add_detail_info ,(select name from account a where a.seq = #{accountSeq}) as account_name from coaching_question_detail_info cqdi where 1=1
and cqdi.category_cd = #{categoryCd}
and cqdi.step_day_cd = #{stepDayCd}
and cqdi.progress_type_cd = #{progressTypeCd}
and cqdi.detail_seq = #{detailSeq}
order by cqdi.category_cd,cqdi.step_day_cd,cqdi.progress_type_cd,cqdi.detail_seq

select cuai.account_seq ,cuai.category_cd ,cuai.step_day_cd ,cuai.progress_type_cd ,cuai.answer_choice_seq ,cuai.answer_choice ,cuai.ref_val1 ,cuai.ref_val2 ,cuai.ref_val3 ,cuai.ref_val4 ,cuai.ref_val5 ,(select name from account a where a.seq = #{accountSeq}) as account_name from coaching_user_answer_info cuai where 1=1 and cuai.account_seq = #{accountSeq}
and cuai.category_cd = #{categoryCd}
and cuai.step_day_cd = #{stepDayCd}
and cuai.progress_type_cd = #{progressTypeCd}
and cuai.answer_choice_seq = #{answerChoiceSeq}
order by cuai.account_seq,cuai.category_cd,cuai.step_day_cd,cuai.progress_type_cd,cuai.answer_choice_seq

        select count(*) as answerCnt
          from coaching_user_answer_info cuai
         where 1=1
		   and account_seq = #{accountSeq}
		   and category_cd = #{categoryCd}
		   and step_day_cd = #{stepDayCd}
		   and progress_type_cd = #{progressTypeCd}
		   and answer_choice_seq = #{answerChoiceSeq}

