delete from coaching_user_answer_info
 where account_seq = #{accountSeq}
   and category_cd = #{categoryCd}
   and step_day_cd = #{stepDayCd}

mapper.update:
		update coaching_user_answer_info
		   set answer_choice = #{answerChoice}
		      ,ref_val1 = #{refVal1}
              ,ref_val2 = #{refVal2}
              ,ref_val3 = #{refVal3}
              ,ref_val4 = #{refVal4}
              ,ref_val5 = #{refVal5}
		      ,updated_at = now()
		 where account_seq = #{accountSeq}
		   and category_cd = #{categoryCd}
		   and step_day_cd = #{stepDayCd}
		   and progress_type_cd = #{progressTypeCd}
		   and answer_choice_seq = #{answerChoiceSeq}

mapper.insert:
        insert into coaching_user_answer_info
            (account_seq
            ,category_cd
            ,step_day_cd
            ,progress_type_cd
            ,answer_choice_seq
            ,answer_choice
            ,ref_val1
            ,ref_val2
            ,ref_val3
            ,ref_val4
            ,ref_val5)
         select #{accountSeq}
               ,#{categoryCd}
               ,#{stepDayCd}
               ,#{progressTypeCd}
               ,a.answerChoiceSeq
               ,#{answerChoice}
               ,#{refVal1}
               ,#{refVal2}
               ,#{refVal3}
               ,#{refVal4}
               ,#{refVal5}
           from (select coalesce(max(answer_choice_seq),0) + 1 as answerChoiceSeq
                   from coaching_user_answer_info
                  where account_seq = #{accountSeq}
		            and category_cd = #{categoryCd}
		            and step_day_cd = #{stepDayCd}
		            and progress_type_cd = #{progressTypeCd}
                ) a

