select exercise_type_cd , index_num , difficulty_cd , eng_name , kor_name , (select url from cm_contents_video ccv where ccv.video_type_cd = concat(a.exercise_type_cd,a.difficulty_cd) and ccv.priority = a.index_num and ccv.use_yn = 'Y' ) from coaching_exercise_contents_mst a where 1 = 1
and exercise_type_cd = #{exerciseTypeCd}
